import{_ as e,o as d,c as l,ao as o}from"./chunks/framework.CKOtou8s.js";const g=JSON.parse('{"title":"API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"api.md","filePath":"api.md","lastUpdated":null}'),a={name:"api.md"};function r(i,t,n,s,c,f){return d(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="API-Reference" tabindex="-1">API Reference <a class="header-anchor" href="#API-Reference" aria-label="Permalink to &quot;API Reference {#API-Reference}&quot;">​</a></h1><p>The exported functions and types, grouped by topic. In the Julia REPL, <code>?name</code> shows the docstring of a function.</p><h2 id="Types" tabindex="-1">Types <a class="header-anchor" href="#Types" aria-label="Permalink to &quot;Types {#Types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>MT2DMesh</code></td><td style="text-align:left;">2D tensor mesh (nodes, cells, receivers, frequencies, topographic air)</td></tr><tr><td style="text-align:left;"><code>FwdCtrl2D</code>, <code>InvCtrl2D</code>, <code>Cov2D</code></td><td style="text-align:left;"><code>fwd.ctrl</code>, <code>inv.ctrl</code> (GN, NLCG) and covariance file contents</td></tr><tr><td style="text-align:left;"><code>VFSACtrl2D</code></td><td style="text-align:left;">VFSA control file contents</td></tr><tr><td style="text-align:left;"><code>InvCtrl1D</code></td><td style="text-align:left;">1D inversion control (GN or VFSA)</td></tr><tr><td style="text-align:left;"><code>Topo2D</code></td><td style="text-align:left;">Topography points (WGS84 lat, lon, elevation)</td></tr><tr><td style="text-align:left;"><code>MT2DResponse</code></td><td style="text-align:left;">2D forward response (TE/TM apparent resistivity, phase, impedance)</td></tr><tr><td style="text-align:left;"><code>ModelFile2D</code></td><td style="text-align:left;">Parsed 2D model file</td></tr><tr><td style="text-align:left;"><code>DataFile2D</code></td><td style="text-align:left;">Parsed 2D data file</td></tr><tr><td style="text-align:left;"><code>FitSummary2D</code></td><td style="text-align:left;">Misfit summary (χ², RMS, count)</td></tr><tr><td style="text-align:left;"><code>Inv2DOptions</code></td><td style="text-align:left;">Algorithm-independent 2D inversion controls</td></tr><tr><td style="text-align:left;"><code>Inv2DResult</code></td><td style="text-align:left;">Recovered model, fit, history, and stopping reason</td></tr><tr><td style="text-align:left;"><code>AbstractInversion2D</code></td><td style="text-align:left;">Supertype of 2D deterministic inversion algorithms</td></tr><tr><td style="text-align:left;"><code>GaussNewton2DConfig</code></td><td style="text-align:left;">Damped Gauss-Newton algorithm settings</td></tr><tr><td style="text-align:left;"><code>GaussNewton2DResult</code></td><td style="text-align:left;"><code>Inv2DResult</code> produced by Gauss-Newton</td></tr><tr><td style="text-align:left;"><code>NLCG2DConfig</code></td><td style="text-align:left;">Preconditioned NLCG algorithm settings</td></tr><tr><td style="text-align:left;"><code>NLCG2DResult</code></td><td style="text-align:left;"><code>Inv2DResult</code> produced by NLCG</td></tr><tr><td style="text-align:left;"><code>VFSA2DConfig</code></td><td style="text-align:left;">VFSA 2D (and 1D) inversion parameters; <code>VFSA2DConfig(ctrl::VFSACtrl2D)</code> from a control file</td></tr><tr><td style="text-align:left;"><code>VFSA3DMTConfig</code></td><td style="text-align:left;">VFSA 3D inversion parameters</td></tr><tr><td style="text-align:left;"><code>WS3DModel</code></td><td style="text-align:left;">3D resistivity model in WS3D format</td></tr><tr><td style="text-align:left;"><code>RBFMap</code></td><td style="text-align:left;">Gaussian-RBF mapping for 3D parameterization</td></tr><tr><td style="text-align:left;"><code>Data</code> / <code>Model</code></td><td style="text-align:left;">3D data and model containers</td></tr></tbody></table><h2 id="1D-Functions" tabindex="-1">1D Functions <a class="header-anchor" href="#1D-Functions" aria-label="Permalink to &quot;1D Functions {#1D-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>mt1d_impedance(f, ρ, h)</code></td><td style="text-align:left;">Layered-earth surface impedance by the recursion</td></tr><tr><td style="text-align:left;"><code>mt1d_layers(f; ...)</code>, <code>mt1d_skin_depth(ρ, f)</code></td><td style="text-align:left;">Skin-depth layering, skin depth</td></tr><tr><td style="text-align:left;"><code>mt1d_frechet(f, ρ, h)</code>, <code>WriteFrechet1D(path, h, ρ, site)</code></td><td style="text-align:left;">G = ∂Z/∂log10 ρ, and its file</td></tr><tr><td style="text-align:left;"><code>MakeMesh1D(data; ...)</code></td><td style="text-align:left;">Skin-depth layering and background resistivity of every site</td></tr><tr><td style="text-align:left;"><code>mt1d_site_data(data, i; mode)</code></td><td style="text-align:left;">One site as a 1D survey; <code>:DET</code> gives √det Z</td></tr><tr><td style="text-align:left;"><code>ReadInvCtrl1D</code>, <code>WriteInvCtrl1D</code></td><td style="text-align:left;">1D inversion control</td></tr><tr><td style="text-align:left;"><code>ForwardSolve1D(model, data; mode)</code></td><td style="text-align:left;">File forward run, writes <code>data.pred</code></td></tr><tr><td style="text-align:left;"><code>Invert1D(data, inv, meshes)</code></td><td style="text-align:left;">1D GN or VFSA inversion, every site on its own</td></tr><tr><td style="text-align:left;"><code>PlotInversion1D(run)</code></td><td style="text-align:left;">Model, data fit and convergence plots per site</td></tr><tr><td style="text-align:left;"><code>PlotModel1D(model)</code>, <code>plot_mt1d_model(h, models)</code></td><td style="text-align:left;">Resistivity-depth steps</td></tr><tr><td style="text-align:left;"><code>plot_mt1d_convergence(histories)</code></td><td style="text-align:left;">GN or VFSA convergence</td></tr></tbody></table><h2 id="2D-Functions" tabindex="-1">2D Functions <a class="header-anchor" href="#2D-Functions" aria-label="Permalink to &quot;2D Functions {#2D-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ReadModel2D</code>, <code>WriteModel2D</code></td><td style="text-align:left;">ModEM-layout model files (earth cells, air tagged 1e17)</td></tr><tr><td style="text-align:left;"><code>load_data2d</code>, <code>write_data2d</code></td><td style="text-align:left;">ModEM Full_Impedance data (ZXY = TE, ZYX = TM), <code>[mV/km]/[nT]</code></td></tr><tr><td style="text-align:left;"><code>EstimateStrike2D(data)</code></td><td style="text-align:left;">Phase tensor strike of a survey, with consistency and skew</td></tr><tr><td style="text-align:left;"><code>StrikeData2D(data, strike)</code>, <code>RotateData2D(data, strike)</code></td><td style="text-align:left;">Data rotated to the strike frame (<code>nothing</code> = auto)</td></tr><tr><td style="text-align:left;"><code>RotateToStrike2D(path; strike)</code></td><td style="text-align:left;">Write the rotated data as <code>&lt;stem&gt;-r&lt;ext&gt;</code></td></tr><tr><td style="text-align:left;"><code>ReadFwdCtrl2D</code>, <code>WriteFwdCtrl2D</code>, <code>ReadInvCtrl2D</code>, <code>WriteInvCtrl2D</code>, <code>ReadCov2D</code>, <code>WriteCov2D</code></td><td style="text-align:left;">Control and covariance files</td></tr><tr><td style="text-align:left;"><code>ReadVFSACtrl2D</code>, <code>WriteVFSACtrl2D</code>, <code>ReadMask2D</code>, <code>WriteMask2D</code></td><td style="text-align:left;">VFSA control and <code>mask.ctrl</code></td></tr><tr><td style="text-align:left;"><code>Mesh2DFromInputs(model, data, fwd)</code></td><td style="text-align:left;">Solver mesh and resistivity, air from <code>fwd.ctrl</code>, stations snapped to the ground</td></tr><tr><td style="text-align:left;"><code>BuildMesh2D(; ...)</code></td><td style="text-align:left;">Padded profile mesh</td></tr><tr><td style="text-align:left;"><code>build_default_mt2d_mesh()</code></td><td style="text-align:left;">Small benchmark mesh of the tests</td></tr><tr><td style="text-align:left;"><code>build_mt2d_halfspace_model(mesh)</code></td><td style="text-align:left;">Uniform earth with the mesh&#39;s air</td></tr><tr><td style="text-align:left;"><code>mt2d_geometric_layers(f; ...)</code></td><td style="text-align:left;">MakeMesh3D-style layers from skin depths</td></tr><tr><td style="text-align:left;"><code>mt2d_skin_depth_layers(f; ...)</code></td><td style="text-align:left;">Skin-depth core layers with geometric padding below</td></tr><tr><td style="text-align:left;"><code>mt2d_air_layers(n, thickness, growth)</code></td><td style="text-align:left;">Air layer thicknesses of <code>fwd.ctrl</code></td></tr><tr><td style="text-align:left;"><code>mt2d_skin_depth(ρ, f)</code></td><td style="text-align:left;">Skin depth in metres</td></tr><tr><td style="text-align:left;"><code>mt2d_air_mask(mesh)</code>, <code>mt2d_topo_air(mesh)</code></td><td style="text-align:left;">Air cells, topographic air per column</td></tr><tr><td style="text-align:left;"><code>mt2d_receiver_depths(mesh)</code>, <code>mt2d_receiver_columns(mesh)</code>, <code>mt2d_station_offsets(mesh, data)</code></td><td style="text-align:left;">Station ground depths, columns and snapping</td></tr><tr><td style="text-align:left;"><code>ReadTopo2D</code>, <code>WriteTopo2D</code></td><td style="text-align:left;"><code>topo.dat</code></td></tr><tr><td style="text-align:left;"><code>mt2d_profile_topography(topo, data)</code></td><td style="text-align:left;">Topography projected onto the profile</td></tr><tr><td style="text-align:left;"><code>Topography2D(model, data, topo; water)</code></td><td style="text-align:left;">Model with topography and water, mask, data Z</td></tr><tr><td style="text-align:left;"><code>Mask2D(model; water, fixed_below_m, fixed)</code></td><td style="text-align:left;">Mask of <code>cov.ctrl</code> and <code>mask.ctrl</code></td></tr><tr><td style="text-align:left;"><code>mt2d_ground(model)</code></td><td style="text-align:left;">Ground depth of each column</td></tr><tr><td style="text-align:left;"><code>MakeMesh2D(data; ...)</code></td><td style="text-align:left;">Inversion inputs from a data file (batch or GUI)</td></tr><tr><td style="text-align:left;"><code>run_mt2d_forward(mesh, ρ)</code>, <code>Forward2D(mesh, ρ)</code></td><td style="text-align:left;">TE/TM forward solve</td></tr><tr><td style="text-align:left;"><code>data_from_response2d(response; ...)</code></td><td style="text-align:left;"><code>DataFile2D</code> of a forward response, with errors</td></tr><tr><td style="text-align:left;"><code>build_mt2d_data_template(mesh; ...)</code>, <code>write_mt2d_data_template(path, mesh; ...)</code></td><td style="text-align:left;">Empty data file of a mesh&#39;s stations and frequencies</td></tr><tr><td style="text-align:left;"><code>ForwardSolve2D(model, data, fwd)</code></td><td style="text-align:left;">File forward run, writes <code>data.pred</code></td></tr><tr><td style="text-align:left;"><code>chi2_rms2d(obs, pred)</code></td><td style="text-align:left;">Misfit</td></tr><tr><td style="text-align:left;"><code>Invert2D(start, data, fwd, inv, cov, prior)</code></td><td style="text-align:left;">Six-file GN or NLCG inversion</td></tr><tr><td style="text-align:left;"><code>Invert2D(mesh, initial, observed; algorithm, options, ...)</code></td><td style="text-align:left;">In-memory deterministic inversion</td></tr><tr><td style="text-align:left;"><code>GaussNewton2D(...)</code>, <code>NLCG2D(...)</code></td><td style="text-align:left;"><code>Invert2D</code> shorthands</td></tr><tr><td style="text-align:left;"><code>inv2d_frechet(problem, state)</code></td><td style="text-align:left;">Data-weighted Fréchet derivative C_D^{-1/2} G in log10 resistivity</td></tr><tr><td style="text-align:left;"><code>inv2d_gradient(problem, state[, G])</code></td><td style="text-align:left;">Objective gradient (explicit or adjoint)</td></tr><tr><td style="text-align:left;"><code>FrechetDerivative2D(mesh, ρ; ...)</code></td><td style="text-align:left;">Explicit Fréchet derivative G = ∂g/∂m</td></tr><tr><td style="text-align:left;"><code>ApplyFrechet2D(mesh, ρ, δm; ...)</code></td><td style="text-align:left;">δd = G δm</td></tr><tr><td style="text-align:left;"><code>ApplyFrechetTranspose2D(mesh, ρ, δd̂; ...)</code></td><td style="text-align:left;">δm̂ = Gᵗ δd̂</td></tr><tr><td style="text-align:left;"><code>WriteFrechet2D(path, mesh, ρ, data)</code></td><td style="text-align:left;">G of a data file&#39;s impedances</td></tr><tr><td style="text-align:left;"><code>PlotInversion2D(run)</code></td><td style="text-align:left;">Standard plots of a run</td></tr><tr><td style="text-align:left;"><code>PlotData2D(data)</code>, <code>PlotModel2D(model)</code></td><td style="text-align:left;">Plots of files</td></tr><tr><td style="text-align:left;"><code>plot_mt2d_model</code>, <code>plot_mt2d_mesh</code>, <code>plot_mt2d_data_fit</code>, <code>plot_mt2d_site_curves</code>, <code>plot_inv2d_convergence</code>, <code>plot_vfsa2d_convergence</code></td><td style="text-align:left;">Plot building blocks</td></tr></tbody></table><h2 id="VFSA-Inversion" tabindex="-1">VFSA Inversion <a class="header-anchor" href="#VFSA-Inversion" aria-label="Permalink to &quot;VFSA Inversion {#VFSA-Inversion}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>VFSA2D(start, data, fwd, vfsa, mask)</code></td><td style="text-align:left;">Five-file 2D VFSA: no covariance, no prior</td></tr><tr><td style="text-align:left;"><code>VFSA2D(mesh, ρ0, observed; config, ...)</code></td><td style="text-align:left;">In-memory 2D (and 1D) VFSA with threaded chains and ensemble</td></tr><tr><td style="text-align:left;"><code>mt2d_ensemble(models)</code></td><td style="text-align:left;">Cell-wise log10 mean, median, std, p05, p95</td></tr><tr><td style="text-align:left;"><code>AnalyseEnsemble2D(run_dir)</code></td><td style="text-align:left;">Recompute the ensemble of a run</td></tr><tr><td style="text-align:left;"><code>VFSA3DMT(model; dobs_path, cfg)</code></td><td style="text-align:left;">Run the 3D VFSA inversion workflow</td></tr><tr><td style="text-align:left;"><code>AnalyseEnsemble3D(dir)</code></td><td style="text-align:left;">Compute 3D ensemble mean/median/std</td></tr><tr><td style="text-align:left;"><code>core_statistics(cores)</code></td><td style="text-align:left;">Element-wise mean, median, std over 3D cubes</td></tr></tbody></table><h2 id="3D-Functions" tabindex="-1">3D Functions <a class="header-anchor" href="#3D-Functions" aria-label="Permalink to &quot;3D Functions {#3D-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>load_data_modem(path)</code></td><td style="text-align:left;">Load 3D data file, with its rotation history</td></tr><tr><td style="text-align:left;"><code>rotate_data(path_or_data, angle; kind)</code></td><td style="text-align:left;">Rotate Z and tipper for a mesh, a strike or declination, see <a href="./data/rotation">rotation</a></td></tr><tr><td style="text-align:left;"><code>RotationStep</code></td><td style="text-align:left;">One step of a data file&#39;s rotation history</td></tr><tr><td style="text-align:left;"><code>load_model_modem(path)</code></td><td style="text-align:left;">Load 3D model file</td></tr><tr><td style="text-align:left;"><code>write_model_modem(path, model)</code></td><td style="text-align:left;">Write 3D model file</td></tr><tr><td style="text-align:left;"><code>chi2_and_rms(obs, pred)</code></td><td style="text-align:left;">Compute 3D misfit</td></tr><tr><td style="text-align:left;"><code>phase_tensor(Zxx, Zxy, Zyx, Zyy)</code></td><td style="text-align:left;">Phase tensor invariants for one site and period</td></tr><tr><td style="text-align:left;"><code>induction_vector(Tzx, Tzy; convention)</code></td><td style="text-align:left;">Induction arrow components from the tipper</td></tr><tr><td style="text-align:left;"><code>phase_tensors_from_data(d)</code></td><td style="text-align:left;">Phase tensors for every period and site</td></tr><tr><td style="text-align:left;"><code>induction_vectors_from_data(d; convention)</code></td><td style="text-align:left;">Induction vectors for every period and site</td></tr><tr><td style="text-align:left;"><code>has_tipper_data(d)</code></td><td style="text-align:left;">Whether a data set carries usable tippers</td></tr><tr><td style="text-align:left;"><code>write_ptiv_gis(data_file; ...)</code></td><td style="text-align:left;">Write phase tensor / induction vector shapefiles per period</td></tr><tr><td style="text-align:left;"><code>PlotPTIVMap(data_file; ...)</code></td><td style="text-align:left;">Interactive phase tensor and induction vector map</td></tr></tbody></table><h2 id="3D-Meshes" tabindex="-1">3D Meshes <a class="header-anchor" href="#3D-Meshes" aria-label="Permalink to &quot;3D Meshes {#3D-Meshes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>MakeMesh3D(data; ...)</code></td><td style="text-align:left;">Start model and ModEM covariance from a data file (batch or GUI), see <a href="./data/mesh3d">3D meshes</a></td></tr><tr><td style="text-align:left;"><code>MeshToMesh(model, data, target)</code></td><td style="text-align:left;">Resample a model onto another mesh, with matching data and covariance</td></tr><tr><td style="text-align:left;"><code>extract_topography</code>, <code>write_topography</code>, <code>read_topography</code></td><td style="text-align:left;">Ground surface of a 3D model</td></tr><tr><td style="text-align:left;"><code>extract_bathymetry</code>, <code>write_bathymetry</code>, <code>read_bathymetry</code></td><td style="text-align:left;">Sea floor of a 3D model</td></tr><tr><td style="text-align:left;"><code>air_mask_from_topography</code>, <code>air_mask_from_model</code></td><td style="text-align:left;">Air cells of a 3D model</td></tr><tr><td style="text-align:left;"><code>water_mask_from_bathymetry</code>, <code>water_mask_from_model</code></td><td style="text-align:left;">Water cells of a 3D model</td></tr><tr><td style="text-align:left;"><code>chi2_and_rms_distorted(obs, pred; damping)</code></td><td style="text-align:left;">3D misfit after per-site galvanic distortion correction</td></tr></tbody></table><h2 id="WS3D-Model-I/O" tabindex="-1">WS3D Model I/O <a class="header-anchor" href="#WS3D-Model-I/O" aria-label="Permalink to &quot;WS3D Model I/O {#WS3D-Model-I/O}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Type</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>WS3DModel</code></td><td style="text-align:left;">3D resistivity model in WS3D format (log₁₀ internal)</td></tr><tr><td style="text-align:left;"><code>load_ws3d_model(path)</code></td><td style="text-align:left;">Load a WS3D model file</td></tr><tr><td style="text-align:left;"><code>read_ws3d_model(path)</code></td><td style="text-align:left;">Alias for <code>load_ws3d_model</code></td></tr><tr><td style="text-align:left;"><code>write_ws3d_model(path, ...)</code></td><td style="text-align:left;">Write a WS3D model file</td></tr></tbody></table><h2 id="Core-Utilities" tabindex="-1">Core Utilities <a class="header-anchor" href="#Core-Utilities" aria-label="Permalink to &quot;Core Utilities {#Core-Utilities}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>edges_from_centers(c)</code></td><td style="text-align:left;">Cell-edge coordinates from cell centres</td></tr><tr><td style="text-align:left;"><code>core_indices(c; tol)</code></td><td style="text-align:left;">Index range of the unpadded core cells</td></tr><tr><td style="text-align:left;"><code>z_indices_for_max_depth(zc, d)</code></td><td style="text-align:left;">Depth-limited vertical index range</td></tr><tr><td style="text-align:left;"><code>lateral_core_ranges(m; tol)</code></td><td style="text-align:left;"><code>(ix, iy)</code> core ranges for a model</td></tr><tr><td style="text-align:left;"><code>core_view(m; tol)</code></td><td style="text-align:left;">View into the core resistivity block</td></tr><tr><td style="text-align:left;"><code>RBFMap</code></td><td style="text-align:left;">Gaussian-RBF mapping structure</td></tr><tr><td style="text-align:left;"><code>build_rbf_map(m, ix, iy, n, rng)</code></td><td style="text-align:left;">Build a 3D RBF control-point map</td></tr><tr><td style="text-align:left;"><code>apply_rbf_map!(delta, rbf, params)</code></td><td style="text-align:left;">Apply RBF perturbations to a 3D field</td></tr></tbody></table>',18)])])}const x=e(a,[["render",r]]);export{g as __pageData,x as default};
